import{_ as s,C as n,c as a,o as i,a3 as e,G as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Receipts","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/operations/receipts.md","filePath":"master/supply-chain/inventories/operations/receipts.md","lastUpdated":1792041590000}'),g={name:"master/supply-chain/inventories/operations/receipts.md"};function l(d,t,c,h,p,u){const o=n("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=e('<h1 id="receipts" tabindex="-1">Receipts <a class="header-anchor" href="#receipts" aria-label="Permalink to &quot;Receipts&quot;">​</a></h1><p>A receipt records goods that arrive from a vendor. When you validate it, the quantities are added to your stock. Most receipts are created for you when you confirm a purchase order, so your job is to check the delivery and click <strong>Validate</strong>.</p><blockquote><p><strong>In simple words:</strong> A receipt says &quot;the vendor delivered this&quot;. Validate it and the products appear in your stock.</p></blockquote><p>Open <code>Inventory → Operations → Transfers → Receipts</code>.</p><h2 id="worked-scenario-receive-po-3" tabindex="-1">Worked scenario: receive PO/3 <a class="header-anchor" href="#worked-scenario-receive-po-3" aria-label="Permalink to &quot;Worked scenario: receive PO/3&quot;">​</a></h2><p>Consolidated Components sent the goods of purchase order <strong>PO/3</strong>: 15 <strong>SSD 512GB</strong> and 10 <strong>Laptop Battery</strong>.</p><ol><li>Confirm the purchase order. See <a href="./../../purchase/orders/purchase-orders.html">Purchase orders</a>.</li><li>Open <code>Inventory → Operations → Transfers → Receipts</code>. The receipt <strong>WH/IN/11</strong> is in the list with <strong>Source Document</strong> <strong>PO/3</strong>.</li></ol>',7)),r(o,{src:"/images1/inventory/rcpt_list_ready.png",alt:"Receipts list showing WH/IN/11 with source document PO/3 in Ready state"}),t[1]||(t[1]=e("<p>You can also reach it from the order. Open the purchase order. The switcher at the top shows <strong>View</strong>, <strong>Edit</strong>, <strong>Vendor Bills</strong> and <strong>Receipts</strong>. Click <strong>Receipts</strong> to open the sub page <strong>Manage PO/3 Receipts</strong>.</p>",1)),r(o,{src:"/images1/inventory/rcpt_from_po.png",alt:"Manage PO/3 Receipts sub page of purchase order PO/3 listing WH/IN/11"}),t[2]||(t[2]=e('<ol start="3"><li>Click <strong>WH/IN/11</strong>. The state bar shows <strong>Draft</strong>, <strong>Waiting</strong>, <strong>Ready</strong>, <strong>Done</strong> and <strong>Canceled</strong>, and <strong>Ready</strong> is highlighted.</li><li>Check the <strong>Operations</strong> tab. The <strong>Demand</strong> column is what you ordered.</li></ol>',1)),r(o,{src:"/images1/inventory/rcpt_view_ready.png",alt:"Receipt WH/IN/11 Operations tab with SSD 512GB demand 15 and Laptop Battery demand 10"}),t[3]||(t[3]=e('<ol start="5"><li>Count the goods. If the truck matches, open the <strong>Edit</strong> tab of the <strong>View</strong> / <strong>Edit</strong> / <strong>Moves</strong> switcher. Turn on the <strong>Picked</strong> toggle on each line, or set <strong>Quantity</strong>. Click <strong>Save changes</strong>.</li><li>Click <strong>Validate</strong>.</li></ol>',1)),r(o,{src:"/images1/inventory/rcpt_validate.png",alt:"Receipt WH/IN/11 with the blue Validate button highlighted"}),t[4]||(t[4]=e('<ol start="7"><li>The state changes to <strong>Done</strong>. The <strong>Return</strong>, <strong>Print</strong> and <strong>Next Transfer</strong> buttons replace <strong>Validate</strong>. The screenshot below shows <strong>WH/IN/12</strong>, a receipt that is <strong>Done</strong>, while <strong>WH/IN/11</strong> is still <strong>Ready</strong>.</li></ol>',1)),r(o,{src:"/images1/inventory/rcpt_done.png",alt:"Receipt WH/IN/12 in Done state with Return, Print and Next Transfer buttons"}),t[5]||(t[5]=e('<ol start="8"><li>Check stock. Open <code>Inventory → Reporting</code> and search <strong>SSD 512GB</strong>. See <a href="./../reporting/stock-report.html">Stock report</a>.</li></ol><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>On the <strong>Edit</strong> page:</p><ul><li><strong><em>Receive From:</em></strong> The vendor. The purchase order fills it in.</li><li><strong><em>Operation Type:</em></strong> Required. Usually <strong>Receipts</strong>.</li><li><strong><em>Destination Location:</em></strong> Required. The default is <strong>WH/Input</strong>.</li><li><strong><em>Responsible:</em></strong> The person in charge. The default is you.</li><li><strong><em>Scheduled At:</em></strong> The expected arrival. Setting it here applies it to all lines.</li><li><strong><em>Source Document:</em></strong> The order number, such as <strong>PO/3</strong>.</li><li><strong>Description</strong> (<strong>Note</strong> tab): Free text for the team.</li></ul><p>Table columns: <strong><em>Product</em></strong>, <strong>Packaging</strong>, <strong><em>Demand</em></strong>, <strong><em>Quantity</em></strong>, <strong><em>Unit</em></strong>, <strong>Picked</strong>. Click <strong>Add to moves</strong> to add a line.</p><p>To start a receipt by hand, click <strong>New Receipt</strong>. Fill the vendor and the lines. The form has three buttons: <strong>Create</strong>, <strong>Create &amp; create another</strong> and <strong>Cancel</strong>. Click <strong>Create</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>After <strong>Create</strong> you stay on the <strong>Edit</strong> page of the new receipt. You are not sent to the <strong>View</strong> page.</p></div><p>A new receipt starts in <strong>Draft</strong>. Click <strong>Mark as Todo</strong> to confirm it. The <strong>Quantity</strong> of each line then defaults to the full <strong>Demand</strong>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If the product tracks lots or serial numbers, Aureus asks you to supply them before you can validate. See <a href="./stock-moves-and-lots.html">Stock moves and lots</a>.</p></div><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Validation moves stock from <strong>Partners/Vendors</strong> to the destination, here <strong>WH/Input</strong>. The document name uses the <strong>IN</strong> prefix, such as <strong>WH/IN/11</strong>. The state goes from <strong>Ready</strong> to <strong>Done</strong>. The <strong>Received</strong> column on the purchase order updates.</p><p>If you receive less than the demand, a window asks about a backorder. See <a href="./backorders-and-returns.html">Backorders and returns</a>.</p><h2 id="multi-step-warehouses" tabindex="-1">Multi-step warehouses <a class="header-anchor" href="#multi-step-warehouses" aria-label="Permalink to &quot;Multi-step warehouses&quot;">​</a></h2><p>The example warehouse uses three steps. After <strong>WH/IN/12</strong> is done, the goods are not in stock yet. <strong>Next Transfer</strong> opens the follow-up documents: <strong>WH/QC</strong> (quality control) and then <strong>WH/STOR</strong> (storage to <strong>WH/Stock</strong>). Validate each one in turn.</p><p>With one step, goods go straight to <strong>WH/Stock</strong> and no extra document appears. See <a href="./../routes/one-step-flow.html">One-step flow</a>, <a href="./../routes/two-step-flow.html">Two-step flow</a> and <a href="./../routes/three-step-flow.html">Three-step flow</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Mark as Todo:</strong> confirms a <strong>Draft</strong> receipt. Only <strong>Draft</strong> receipts show it.</li><li><strong>Validate:</strong> processes the receipt and sets it to <strong>Done</strong>. Click <strong>Save changes</strong> first if you edited the lines.</li><li><strong>Cancel:</strong> stops it before any stock arrives.</li><li><strong>Delete:</strong> removes a <strong>Draft</strong> or <strong>Ready</strong> receipt.</li><li><strong>Return:</strong> sends goods back after <strong>Done</strong>.</li><li><strong>Print:</strong> see <a href="./print-documents.html">Print documents</a>.</li></ul><p>A <strong>Draft</strong> or <strong>Ready</strong> receipt shows <strong>Validate</strong>, <strong>Cancel</strong>, <strong>Print</strong> and <strong>Delete</strong>. A <strong>Draft</strong> receipt also shows <strong>Mark as Todo</strong>. A <strong>Done</strong> receipt shows <strong>Return</strong>, <strong>Print</strong> and <strong>Next Transfer</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Transfers</a></li><li><a href="./deliveries.html">Deliveries</a></li><li><a href="./backorders-and-returns.html">Backorders and returns</a></li><li><a href="./../../purchase/orders/purchase-orders.html">Purchase orders</a></li></ul>',20))])}const _=s(g,[["render",l]]);export{f as __pageData,_ as default};
